import gurobipy as gp
from gurobipy import GRB
shelves = []
capacity = {}
for rec in LEGACY_RECORDS:
    if rec['source'] == 'capacity.csv':
        shelfid = rec['values']['ShelfID']
        shelves.append(shelfid)
        capacity[shelfid] = float(rec['values']['Capacity'])
products = []
weight = {}
value = {}
for rec in LEGACY_RECORDS:
    if rec['source'] == 'products.csv':
        pname = rec['values']['ProductName']
        products.append(pname)
        weight[pname] = float(rec['values']['Weight'])
        value[pname] = float(rec['values']['Value'])
if len(shelves) != 10:
    raise ValueError('Expected 10 shelves, got %d' % len(shelves))
if len(products) != 20:
    raise ValueError('Expected 20 products, got %d' % len(products))
for s in shelves:
    if s not in capacity:
        raise ValueError(f'Missing capacity for shelf {s}')
for p in products:
    if p not in weight or p not in value:
        raise ValueError(f'Missing weight or value for product {p}')
m = gp.Model('retail_display_allocation')
x = m.addVars(shelves, products, lb=0, vtype=GRB.INTEGER, name='')
m.setObjective(gp.quicksum((value[p] * x[s, p] for s in shelves for p in products)), GRB.MAXIMIZE)
m.addConstrs((gp.quicksum((weight[p] * x[s, p] for p in products)) <= capacity[s] for s in shelves), name='')
first_product = products[0]
m.addConstr(gp.quicksum((x[s, first_product] for s in shelves)) >= 5, name='min_smartphone')
m.Params.MIPGap = 0.0001
m.optimize()
if m.Status == GRB.OPTIMAL:
    print(f'ObjVal: {m.ObjVal}')
    for var in m.getVars():
        print(f'{var.VarName}: {var.X}')
else:
    print(f'Solver status: {m.Status}')